        Term(id: "zaatar", word: "Za'atar", meaning: "A Levantine blend of dried thyme or hyssop with sesame and sumac, met on flatbread with olive oil, over labneh, and scattered across roasted vegetables."),
    ]

    static let glossary: [Term] = termsChunk0 + termsChunk1 + termsChunk2 + termsChunk3

    static let guideByID: [String: Guide] = Dictionary(uniqueKeysWithValues: guides.map { ($0.id, $0) })
}
